function participants_held(array $rows,?array $model):void {
    if(!$rows)return;$map=array_column($model['rows']??[],null,'id');
    ?><details class="participants-held"><summary><span class="participants-held-count"><?= count($rows) ?></span><span><strong><?= count($rows) ?> siswa belum dapat diproses</strong><small>Periksa perbedaan penempatan atau status sebelum melanjutkan.</small></span><span class="participants-held-chevron" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m6 9 6 6 6-6"/></svg></span></summary><div class="participants-held-list"><?php foreach($rows as $r):$p=$map[(int)$r['source_placement_id']]??null; ?><article><header><div><strong><?= participants_e($r['NAMA']) ?></strong><small>NIS <?= participants_e($r['NO_INDUK']) ?></small></div><a class="btn btn-ghost btn-sm" href="siswa/daftar.php?edit=<?= (int)$r['student_id'] ?>">Periksa Data Siswa</a></header><dl><div><dt>Penempatan asal</dt><dd><?= participants_e(($p['rombel']??$r['kelas_label']).' · '.($model['source_year']??'')) ?></dd></div><div><dt>Kelas/Rombel aktif</dt><dd><?= participants_e($p['current_rombel']??participants_level_label($r['active_level'])) ?></dd></div></dl><p><?= participants_e($r['blocked_reason']) ?></p></article><?php endforeach; ?></div></details><?php
}
